import { useState } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";

export default function Register() {
  const [mobile, setMobile] = useState("");
  const nav = useNavigate();

  const register = async () => {
    await axios.post("http://localhost:8080/api/register?mobile=" + mobile);
    nav("/verify?mobile=" + mobile);
  };

  return (
    <div>
      <h2>Register</h2>
      <input value={mobile} onChange={(e)=>setMobile(e.target.value)} placeholder="Mobile No" />
      <button onClick={register}>Send OTP</button>
    </div>
  );
}
